13	```html
14	<!doctype html>
15	<html lang="en">
16	<head>
17	<meta charset="utf-8">
18	<title>Portfolio board</title>
19	<style>
20	  :root{--bg:#12141a;--panel:#1a1d26;--panel2:#20242f;--line:#2c3140;--ink:#e6e9f0;
21	        --dim:#98a0b3;--faint:#6b7385;--accent:#7c8cff;--bad:#ff8b8b}
