36	  .col>h2{margin:0;padding:10px 11px;font-size:11px;letter-spacing:.9px;text-transform:uppercase;
37	          color:var(--dim);border-bottom:1px solid var(--line);display:flex;justify-content:space-between}
38	  .drop{padding:9px;display:flex;flex-direction:column;gap:8px;min-height:70px}
39	  .col.over{outline:2px solid var(--accent);outline-offset:-2px}
40	  .inbox{background:#1b1726;border-color:#3a3050}
41	  .card{background:var(--panel2);border:1px solid var(--line);border-radius:9px;
42	        padding:9px 10px;cursor:grab;position:relative}
43	  .card.open{cursor:default}
44	  .card h3{margin:0 0 5px;font-size:13px;font-weight:600;padding-right:74px;word-break:break-word}
45	  .st{position:absolute;top:6px;right:6px;font-size:10px;padding:3px 6px;border-radius:99px;
46	      background:#0d0f14;color:var(--dim);border:1px solid var(--line);font-family:inherit}
47	  .card p{margin:0;color:var(--dim);font-size:12px;
48	          display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
49	  .bar{height:3px;background:#000;border-radius:99px;margin-top:8px;overflow:hidden}
50	  .bar i{display:block;height:100%;background:var(--accent)}
51	  .rk{color:var(--faint);font-size:10px;margin-top:4px}
52	  .panel{margin-top:9px;padding-top:9px;border-top:1px solid var(--line);
53	         display:flex;flex-direction:column;gap:6px}
54	  .panel label{font-size:10px;letter-spacing:.7px;text-transform:uppercase;color:var(--faint)}
55	  .panel textarea,.panel input{width:100%;background:#0d0f14;color:var(--ink);
56	        border:1px solid var(--line);border-radius:6px;padding:6px 7px;font:12px/1.4 inherit}
57	  .panel .missing{border-color:#7a3030}
58	  .up{font-size:11px;color:var(--dim);background:#0d0f14;border-radius:5px;padding:5px 7px}
59	  .up b{color:var(--faint);font-weight:500}
60	  .warn{font-size:11px;color:var(--bad);background:#2a1616;border:1px solid #5a2626;
61	        border-radius:6px;padding:5px 7px}
