63	         background:#2a1616;color:var(--bad);border:1px solid #5a2626;padding:8px 14px;
64	         border-radius:8px;font-size:12.5px;display:none;max-width:70vw}
65	</style>
66	</head>
67	<body>
68	<header>
69	  <h1>Portfolio board</h1>
70	  <span id="meta" style="color:var(--faint);font-size:12px"></span>
71	  <div class="tabs" id="tabs"></div>
72	  <button class="plain" id="undo">Undo</button>
73	</header>
74	<div id="app"></div>
75	<div class="flash" id="flash"></div>
76	
77	<script>
78	const TOKEN = new URLSearchParams(location.search).get("token") || "";
79	const STAGES = ["idea","grilled","spec","planned","building","shipped"];
80	const STATUSES = ["active","paused","done","dropped"];
81	const ARCHIVED = new Set(["done","dropped"]);
82	let REG = null, lane = "job", openCard = null;
83	
84	function flash(msg){
85	  const f = document.getElementById("flash");
86	  f.textContent = msg; f.style.display = "block";
87	  clearTimeout(flash.t); flash.t = setTimeout(()=>f.style.display="none", 5000);
88	}
89	async function api(path, opts = {}){
90	  const sep = path.includes("?") ? "&" : "?";
91	  const res = await fetch(path + sep + "token=" + encodeURIComponent(TOKEN), {
92	    headers: {"Content-Type":"application/json"}, ...opts
93	  });
94	  if(!res.ok){
95	    let msg = res.statusText;
96	    try { msg = (await res.json()).error || msg; } catch {}
97	    throw new Error(msg);
98	  }
99	  return res.json();
100	}
101	async function load(){ REG = await api("/api/registry"); render(); }
102	
103	// any failed write reloads from disk, so the board never shows a state that was not saved
104	async function write(path, payload, method = "POST"){
105	  try {
106	    await api(path, {method, body: JSON.stringify(payload || {})});
107	  } catch(e){
108	    flash(e.message);
109	  }
110	  await load();
111	}
112	
113	const idx = s => Math.max(0, STAGES.indexOf(s));
114	const live = l => REG.projects
115	  .filter(p => p.lane === l && !ARCHIVED.has(p.status))
116	  .sort((a,b) => (a.rank||1e6) - (b.rank||1e6));
117	
118	let dragged = null;
119	function card(rec, from){
120	  const open = openCard === rec.name;
121	  const d = document.createElement("div");
122	  d.className = "card" + (open ? " open" : "");
123	  d.dataset.name = rec.name;
124	  d.draggable = !open;
125	
126	  const h = document.createElement("h3"); h.textContent = rec.name;
127	  d.append(h);
128	
129	  const sel = document.createElement("select");
130	  sel.className = "st";
131	  STATUSES.forEach(v => {
132	    const o = document.createElement("option");
133	    o.value = v; o.textContent = v; o.selected = v === (rec.status || "active");
134	    sel.append(o);
135	  });
136	  sel.onmousedown = e => e.stopPropagation();
137	  sel.onclick = e => e.stopPropagation();
138	  sel.onchange = e => {
139	    e.stopPropagation();
140	    if(from === "inbox"){ rec.status = sel.value; return; }
141	    write(`/api/project/${encodeURIComponent(rec.name)}`, {status: sel.value});
142	  };
143	  d.append(sel);
144	
145	  if(!open){
146	    const p = document.createElement("p");
147	    p.textContent = rec.purpose || "— no purpose yet —";
148	    d.append(p);
149	  }
150	  if(from !== "inbox"){
151	    const b = document.createElement("div"); b.className = "bar";
152	    const i = document.createElement("i");
153	    i.style.width = ((idx(rec.stage)+1)/STAGES.length*100).toFixed(0) + "%";
154	    b.append(i);
155	    const r = document.createElement("div"); r.className = "rk";
156	    r.textContent = `#${rec.rank ?? "—"} · ${rec.stage || "unstaged"}`;
157	    d.append(b, r);
158	  }
159	  if(open) d.append(panel(rec, from));
160	
161	  d.onclick = () => { openCard = open ? null : rec.name; render(); };
162	  d.addEventListener("dragstart", e => {
163	    dragged = {rec, from};
164	    e.dataTransfer.effectAllowed = "move";
165	    e.dataTransfer.setData("text/plain", rec.name);
166	  });
167	  d.addEventListener("dragend", () => dragged = null);
168	  return d;
169	}
170	
171	function panel(rec, from){
172	  const p = document.createElement("div"); p.className = "panel";
173	  p.onclick = e => e.stopPropagation();
174	  p.onmousedown = e => e.stopPropagation();
175	
176	  const needsFields = from === "inbox";
177	  if(needsFields && (!rec.purpose || !rec.next_action)){
178	    const w = document.createElement("div"); w.className = "warn";
179	    w.textContent = "Drag onto a stage column to promote. Purpose and next action are both required first.";
180	    p.append(w);
181	  }
182	  const field = (key, label, tag) => {
183	    const l = document.createElement("label"); l.textContent = label;
184	    const el = document.createElement(tag);
185	    if(tag === "textarea") el.rows = 3;
186	    el.value = rec[key] || "";
187	    if(!el.value) el.classList.add("missing");
188	    el.oninput = () => { rec[key] = el.value; el.classList.toggle("missing", !el.value); };
189	    el.onchange = () => {
190	      if(from === "inbox") return;             // inbox edits are held until promotion
191	      write(`/api/project/${encodeURIComponent(rec.name)}`, {[key]: el.value});
192	    };
193	    p.append(l, el);
194	  };
195	  field("purpose", "purpose", "textarea");
196	  field("next_action", "next action", "input");
197	
198	  if(from !== "inbox"){
199	    const l = document.createElement("label"); l.textContent = "add update";
200	    const add = document.createElement("input");
201	    add.placeholder = "one line, then Enter";
202	    add.onkeydown = e => {
203	      if(e.key !== "Enter" || !add.value.trim()) return;
204	      write(`/api/project/${encodeURIComponent(rec.name)}`, {note: add.value.trim()});
205	    };
206	    p.append(l, add);
207	    (rec.updates || []).slice(0, 6).forEach(u => {
208	      const d = document.createElement("div"); d.className = "up";
209	      const b = document.createElement("b"); b.textContent = u.date + " ";
210	      d.append(b, document.createTextNode(u.note));
211	      p.append(d);
212	    });
213	    const del = document.createElement("button");
214	    del.className = "plain"; del.textContent = "Delete project";
215	    del.onclick = () => {
216	      if(confirm(`Delete "${rec.name}"? This rewrites portfolio.json.`))
217	        write(`/api/project/${encodeURIComponent(rec.name)}`, null, "DELETE");
218	    };
219	    p.append(del);
220	  }
221	  return p;
222	}
223	
224	function column(title, count, cls){
225	  const c = document.createElement("div"); c.className = "col " + (cls || "");
226	  const h = document.createElement("h2");
227	  const a = document.createElement("span"); a.textContent = title;
228	  const b = document.createElement("span"); b.textContent = count;
229	  h.append(a, b);
230	  const z = document.createElement("div"); z.className = "drop";
231	  c.append(h, z);
232	  return {col: c, zone: z};
233	}
234	
235	function dropTarget(colEl, zoneEl, stage){
236	  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
237	  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
238	  colEl.addEventListener("drop", e => {
239	    e.preventDefault(); colEl.classList.remove("over");
240	    if(!dragged) return;
241	    const cards = [...zoneEl.querySelectorAll(".card")];
242	    let position = cards.length;
243	    for(let i = 0; i < cards.length; i++){
244	      const r = cards[i].getBoundingClientRect();
245	      if(e.clientY < r.top + r.height/2){ position = i; break; }
246	    }
247	    const {rec, from} = dragged;
248	    if(from === "inbox"){
249	      write(`/api/inbox/${encodeURIComponent(rec.name)}/promote`,
250	            {lane, stage, position, purpose: rec.purpose || "", next_action: rec.next_action || ""});
251	    } else {
252	      write("/api/move", {name: rec.name, lane, stage, position});
253	    }
254	  });
255	}
256	
257	function render(){
258	  const app = document.getElementById("app");
259	  app.textContent = "";
260	  const wrap = document.createElement("div"); wrap.className = "cols";
261	
262	  const inbox = REG.inbox || [];
263	  const ib = column("Inbox", inbox.length, "inbox");
264	  inbox.forEach(r => ib.zone.append(card(r, "inbox")));
265	  wrap.append(ib.col);
266	
267	  STAGES.forEach(s => {
268	    const list = live(lane).filter(p => p.stage === s);
269	    const c = column(s, list.length);
270	    list.forEach(p => c.zone.append(card(p, "board")));
271	    dropTarget(c.col, c.zone, s);
272	    wrap.append(c.col);
273	  });
274	
275	  const arch = REG.projects.filter(p => ARCHIVED.has(p.status));
276	  const ac = column("Archive", arch.length);
277	  arch.forEach(p => ac.zone.append(card(p, "board")));
278	  wrap.append(ac.col);
279	  app.append(wrap);
280	
281	  document.getElementById("meta").textContent =
282	    `${REG.projects.length} projects · ${inbox.length} inbox · ${arch.length} archived`;
283	
284	  const tabs = document.getElementById("tabs");
285	  tabs.textContent = "";
286	  ["job","side"].forEach(l => {
287	    const b = document.createElement("button");
288	    b.className = "tab" + (l === lane ? " on" : "");
289	    b.textContent = l;
290	    b.onclick = () => { lane = l; openCard = null; render(); };
291	    tabs.append(b);
292	  });
293	}
294	
295	document.getElementById("undo").onclick = () => write("/api/undo", {});
296	load();
297	</script>
298	</body>
299	</html>
300	```
301	
302	- [ ] **Step 2: Verify the JS parses**
303	
304	Run:
305	```bash
306	node -e "const fs=require('fs');const h=fs.readFileSync('board.html','utf8');new Function(h.match(/<script>([\s\S]*)<\/script>/)[1]);console.log('JS syntax OK')"
307	```
308	Expected: `JS syntax OK`
309	
310	- [ ] **Step 3: Run the full suite**
311	
312	Run: `python3 -m unittest discover -s tests -v`
313	Expected: PASS — the server tests copy `board.html` into their temp dir, so a broken file breaks `test_root_serves_the_page`.
314	
315	- [ ] **Step 4: Drive it against the real registry**
316	
317	```bash
318	python3 board.py
319	```
320	
321	Check by hand, then stop it with ctrl-c:
322	1. Both lanes load; `job` shows 14 live projects, `side` shows 7.
323	2. Drag a card between two stage columns — the `#rank` labels renumber.
324	3. Change a status dropdown, then reload the page — the change survived.
325	4. Open a card, edit the purpose, click away, reload — the edit survived.
326	5. Type an update, press Enter — it appears with today's date.
327	6. Drag `ValdReport` out of Inbox — a red message appears and it stays in the Inbox.
328	7. Fill in its purpose and next action, drag again — it lands on the board.
329	8. Press Undo — the promotion is reversed.
330	
331	- [ ] **Step 5: Verify the registry is still valid after manual testing**
332	
333	```bash
334	python3 -c "import portfolio,pathlib;portfolio.validate(portfolio.load_registry(pathlib.Path('portfolio.json')));print('registry valid')"
335	python3 render.py --no-scan
336	```
337	Expected: `registry valid`, then a successful render.
338	
339	- [ ] **Step 6: Commit**
340	
341	```bash
342	git add board.html portfolio.json
343	git commit -m "feat: board page with drag, status dropdown and inline editing"
344	```
