84	async function api(path, opts = {}){
85	  const sep = path.includes("?") ? "&" : "?";
86	  const res = await fetch(path + sep + "token=" + encodeURIComponent(TOKEN), {
87	    headers: {"Content-Type":"application/json"}, ...opts
88	  });
89	  if(!res.ok){
90	    let msg = res.statusText;
91	    try { msg = (await res.json()).error || msg; } catch {}
